a = 2024
b = f(a)
a_seq = [a]
b_seq = [b]

# Check for small number of terms
for i in range(1, 5):
    a_next = g(b_seq[i-1])
    b_next = f(a_next)
    a_seq.append(a_next)
    b_seq.append(b_next)

print(f"Sequence a (first 5 terms): {a_seq}")
print(f"Sequence b (first 4 terms): {b_seq}")

moduli = [12, 24, 50, 100]
results = {}

for k in moduli:
    divisible_found = False
    # Check a_n
    for term in a_seq:
        if term % k == 0 and term != 0:
            divisible_found = True
            break

    if divisible_found:
        results[k] = "Divisible found in a_n"
        continue

    # Check b_n
    for term in b_seq:
        if term % k == 0 and term != 0:
            divisible_found = True
            break

    if divisible_found:
        results[k] = "Divisible found in b_n"
    else:
        results[k] = "No term found divisible (within 4 steps)"

print("\nConsistency Test Results (k):")
for k, result in results.items():
    print(f"k={k}: {result}")

